function validate([num]) {
  if (typeof num !== 'string' || num.length < 2 || num.length > 80) return 'num needs 2 to 80 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only the digits 0 to 9.';
  return null;
}

