function countBalancedPermutations(num) {
  const MOD = 1_000_000_007;
  // (a * b) % MOD without exceeding 2^53: split b into its high and low 16 bits.
  const multiply = (a, b) => ((a * (b >>> 16)) % MOD * 65536 + a * (b & 65535)) % MOD;
  const n = num.length;
  const count = new Array(10).fill(0);
  let total = 0;
  for (const ch of num) {
    count[Number(ch)]++;
    total += Number(ch);
  }
  if (total % 2 === 1) {
    return 0;
  }
  const target = total / 2;
  const evenSlots = Math.ceil(n / 2);
  const oddSlots = n - evenSlots;
  // choose[a][b] = C(a, b) modulo MOD, built with Pascal's rule.
  const choose = Array.from({ length: evenSlots + 1 }, () => new Array(evenSlots + 1).fill(0));
  for (let a = 0; a <= evenSlots; a++) {
    choose[a][0] = 1;
    for (let b = 1; b <= a; b++) {
      choose[a][b] = (choose[a - 1][b - 1] + choose[a - 1][b]) % MOD;
    }
  }
  // dp[j][s]: ways to place the digits handled so far, using j even slots whose digits sum to s.
  let dp = Array.from({ length: evenSlots + 1 }, () => new Array(target + 1).fill(0));
  dp[0][0] = 1;
  let placed = 0;
  for (let digit = 0; digit <= 9; digit++) {
    const copies = count[digit];
    if (copies === 0) {
      continue;
    }
    const next = Array.from({ length: evenSlots + 1 }, () => new Array(target + 1).fill(0));
    for (let j = 0; j <= Math.min(placed, evenSlots); j++) {
      const oddFree = oddSlots - (placed - j);
      for (let k = 0; k <= copies && j + k <= evenSlots; k++) {
        if (copies - k > oddFree) {
          continue;
        }
        const ways = multiply(choose[evenSlots - j][k], choose[oddFree][copies - k]);
        for (let s = 0; s + k * digit <= target; s++) {
          if (dp[j][s] !== 0) {
            next[j + k][s + k * digit] = (next[j + k][s + k * digit] + multiply(dp[j][s], ways)) % MOD;
          }
        }
      }
    }
    dp = next;
    placed += copies;
  }
  return dp[evenSlots][target];
}

