function countBalancedPermutations(num) {
  // Build every distinct arrangement digit by digit from the remaining counts.
  const left = new Array(10).fill(0);
  for (const ch of num) left[ch.charCodeAt(0) - 48]++;
  let balanced = 0;
  const place = (position, difference) => {
    if (position === num.length) {
      if (difference === 0) balanced++;
      return;
    }
    for (let d = 0; d <= 9; d++) {
      if (left[d] === 0) continue;
      left[d]--;
      place(position + 1, position % 2 === 0 ? difference + d : difference - d);
      left[d]++;
    }
  };
  place(0, 0);
  return balanced % 1000000007;
}

