function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 72 + Math.floor(rand() * 9) : 2 + Math.floor(rand() * 7);
  // Draw from a few distinct digits so that repeats are common.
  const pool = [];
  const kinds = 1 + Math.floor(rand() * (large ? 10 : 4));
  while (pool.length < kinds) {
    const d = Math.floor(rand() * 10);
    if (!pool.includes(d)) pool.push(d);
  }
  const digits = Array.from({ length: n }, () => pool[Math.floor(rand() * kinds)]);
  // An odd digit total always gives 0, so usually flip the parity of the last digit.
  const total = digits.reduce((a, b) => a + b, 0);
  if (total % 2 === 1 && rand() < 0.75) digits[n - 1] = (digits[n - 1] + 1) % 10;
  return [digits.join('')];
}
